#!/usr/bin/env python3
"""Convert a trail bodyDocument.contentJson (ProseMirror-style) back to markdown.

Only the node and mark types the trail actually uses are handled; anything
unexpected raises so the output can't silently lose content.
"""
import json
import sys

KNOWN_NODES = {"doc", "paragraph", "heading", "bulletList", "listItem", "codeBlock", "text"}
KNOWN_MARKS = {"code", "bold", "strong", "italic", "em", "link"}


def inline(nodes):
    out = []
    for n in nodes or []:
        if n["type"] != "text":
            raise SystemExit(f"unexpected inline node: {n['type']}")
        text = n.get("text", "")
        marks = {m["type"] for m in n.get("marks") or []}
        unknown = marks - KNOWN_MARKS
        if unknown:
            raise SystemExit(f"unexpected marks: {unknown}")
        if "code" in marks:
            text = f"`{text}`"
        if marks & {"bold", "strong"}:
            text = f"**{text}**"
        if marks & {"italic", "em"}:
            text = f"*{text}*"
        for m in n.get("marks") or []:
            if m["type"] == "link":
                text = f"[{text}]({m.get('attrs', {}).get('href', '')})"
        out.append(text)
    return "".join(out)


def block(node, depth=0):
    t = node["type"]
    if t not in KNOWN_NODES:
        raise SystemExit(f"unexpected block node: {t}")
    if t == "paragraph":
        return inline(node.get("content"))
    if t == "heading":
        level = (node.get("attrs") or {}).get("level", 1)
        return "#" * level + " " + inline(node.get("content"))
    if t == "codeBlock":
        lang = ((node.get("attrs") or {}).get("language")) or ""
        body = inline(node.get("content"))
        return f"```{lang}\n{body}\n```"
    if t == "bulletList":
        lines = []
        for item in node.get("content") or []:
            if item["type"] != "listItem":
                raise SystemExit(f"unexpected list child: {item['type']}")
            parts = [block(c, depth + 1) for c in item.get("content") or []]
            joined = "\n\n".join(p for p in parts if p)
            first, *rest = joined.split("\n")
            lines.append("  " * depth + "- " + first)
            for line in rest:
                lines.append("  " * depth + ("  " + line if line else ""))
        return "\n".join(lines)
    raise SystemExit(f"unhandled block node: {t}")


doc = json.load(open(sys.argv[1]))["bodyDocument"]["contentJson"]
blocks = [block(n) for n in doc.get("content") or []]
sys.stdout.write("\n\n".join(b for b in blocks if b.strip()) + "\n")

